INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2025-01-01-uruguay-universal-mandate-completes', '2025-01-01', '2025-01', 'From 1 January 2025, essentially all of Uruguay''s remaining VAT taxpayers became required electronic issuers, closing an exemption window DGI had maintained in various forms since the CFE regime began in 2012 -- DGI''s own announcement put electronic documentation at 98% of the total even before the closure took effect.', '<h3>🇺🇾 Uruguay''s electronic-invoicing mandate becomes universal</h3>
<p>In an official communiqué published 28 November 2024, Uruguay''s Dirección General Impositiva (DGI) announced that from 1 January 2025, essentially all remaining VAT contributors -- including those under the "IVA Mínimo" (minimum VAT) regime -- would become required electronic issuers of Comprobante Fiscal Electrónico (CFE), closing an exemption window the agency had maintained in various forms since the CFE regime began under Decreto 36/012 in 2012.</p>
<p>The deadline itself traces to Resolución DGI 2548/023 (approved 30 November 2023), which gave taxpayers already designated for compulsory incorporation until 31 December 2024 to comply, and required anyone newly registering for VAT between May and December 2024 to be issuing electronically before 1 January 2025.</p>
<p>A short, defined list of exemptions remains -- small-scale agriculture, certain construction value-add services, non-resident income tax payers, fully VAT-exempt activity outside free trade zones, and Uruguay''s simplified micro-enterprise regimes. Beyond that narrow list, DGI''s own announcement reported that electronic invoicing already covered 98% of documentation issued nationwide even before the closure took effect -- a striking adoption figure for a mandate over a decade in the making.</p>', 'https://www.gub.uy/direccion-general-impositiva/comunicacion/noticias/facturacion-electronica-incorporacion-restantes-contribuyentes-iva', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2025-01-01-uruguay-universal-mandate-completes', id FROM countries WHERE name_en = 'Uruguay';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-01-01-uruguay-universal-mandate-completes', 'en', 'Uruguay''s electronic-invoicing mandate becomes universal', 'From 1 January 2025, essentially all of Uruguay''s remaining VAT taxpayers became required electronic issuers, closing an exemption window DGI had maintained in various forms since the CFE regime began in 2012 -- DGI''s own announcement put electronic documentation at 98% of the total even before the closure took effect.', '<h3>🇺🇾 Uruguay''s electronic-invoicing mandate becomes universal</h3>
<p>In an official communiqué published 28 November 2024, Uruguay''s Dirección General Impositiva (DGI) announced that from 1 January 2025, essentially all remaining VAT contributors -- including those under the "IVA Mínimo" (minimum VAT) regime -- would become required electronic issuers of Comprobante Fiscal Electrónico (CFE), closing an exemption window the agency had maintained in various forms since the CFE regime began under Decreto 36/012 in 2012.</p>
<p>The deadline itself traces to Resolución DGI 2548/023 (approved 30 November 2023), which gave taxpayers already designated for compulsory incorporation until 31 December 2024 to comply, and required anyone newly registering for VAT between May and December 2024 to be issuing electronically before 1 January 2025.</p>
<p>A short, defined list of exemptions remains -- small-scale agriculture, certain construction value-add services, non-resident income tax payers, fully VAT-exempt activity outside free trade zones, and Uruguay''s simplified micro-enterprise regimes. Beyond that narrow list, DGI''s own announcement reported that electronic invoicing already covered 98% of documentation issued nationwide even before the closure took effect -- a striking adoption figure for a mandate over a decade in the making.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-01-01-uruguay-universal-mandate-completes', 'es', 'El mandato de facturación electrónica de Uruguay se vuelve universal', 'A partir del 1 de enero de 2025, prácticamente todos los contribuyentes de IVA restantes de Uruguay pasaron a ser emisores electrónicos obligatorios, cerrando una ventana de exención que la DGI había mantenido en distintas formas desde que comenzó el régimen de CFE en 2012 -- el propio anuncio de la DGI situó la documentación electrónica en el 98% del total incluso antes de que el cierre entrara en vigor.', '<h3>🇺🇾 El mandato de facturación electrónica de Uruguay se vuelve universal</h3>
<p>En un comunicado oficial publicado el 28 de noviembre de 2024, la Dirección General Impositiva (DGI) de Uruguay anunció que, a partir del 1 de enero de 2025, prácticamente todos los contribuyentes de IVA restantes -- incluidos los del régimen de "IVA Mínimo" -- pasarían a ser emisores electrónicos obligatorios de Comprobante Fiscal Electrónico (CFE), cerrando una ventana de exención que el organismo había mantenido en distintas formas desde que el régimen de CFE comenzó con el Decreto 36/012 en 2012.</p>
<p>El plazo en sí se remonta a la Resolución DGI 2548/023 (aprobada el 30 de noviembre de 2023), que otorgó a los contribuyentes ya designados para la incorporación obligatoria hasta el 31 de diciembre de 2024 para cumplir, y exigió que cualquier persona que se registrara nuevamente en el IVA entre mayo y diciembre de 2024 estuviera emitiendo electrónicamente antes del 1 de enero de 2025.</p>
<p>Queda una lista breve y definida de exenciones -- pequeña agricultura, ciertos servicios de construcción con valor agregado, contribuyentes del impuesto a la renta de no residentes, actividad totalmente exenta de IVA fuera de las zonas francas, y los regímenes simplificados de microempresas de Uruguay. Más allá de esa lista acotada, el propio anuncio de la DGI informó que la facturación electrónica ya cubría el 98% de la documentación emitida a nivel nacional incluso antes de que el cierre entrara en vigor -- una cifra de adopción notable para un mandato que llevaba más de una década gestándose.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-01-01-uruguay-universal-mandate-completes', 'de', 'Uruguays E-Rechnungspflicht wird universell', 'Ab dem 1. Januar 2025 wurden praktisch alle verbleibenden umsatzsteuerpflichtigen Personen Uruguays zu verpflichteten elektronischen Rechnungsstellern, wodurch ein Ausnahmefenster geschlossen wurde, das die DGI seit Beginn des CFE-Regimes im Jahr 2012 in verschiedenen Formen aufrechterhalten hatte -- die DGI selbst gab in ihrer Ankündigung an, dass die elektronische Dokumentation bereits 98 % des Gesamtvolumens erreichte, noch bevor die Schließung in Kraft trat.', '<h3>🇺🇾 Uruguays E-Rechnungspflicht wird universell</h3>
<p>In einer am 28. November 2024 veröffentlichten offiziellen Mitteilung gab Uruguays Dirección General Impositiva (DGI) bekannt, dass ab dem 1. Januar 2025 praktisch alle verbleibenden Umsatzsteuerpflichtigen -- einschließlich jener unter dem Regime "IVA Mínimo" (Mindest-Umsatzsteuer) -- zu verpflichteten elektronischen Ausstellern von Comprobante Fiscal Electrónico (CFE) würden, wodurch ein Ausnahmefenster geschlossen wurde, das die Behörde seit Beginn des CFE-Regimes unter dem Decreto 36/012 im Jahr 2012 in verschiedenen Formen aufrechterhalten hatte.</p>
<p>Die Frist selbst geht auf die Resolución DGI 2548/023 (genehmigt am 30. November 2023) zurück, die Steuerpflichtigen, die bereits für die verpflichtende Einbindung vorgesehen waren, bis zum 31. Dezember 2024 Zeit zur Erfüllung einräumte und verlangte, dass sich jeder, der sich zwischen Mai und Dezember 2024 neu für die Umsatzsteuer registrierte, vor dem 1. Januar 2025 elektronisch abrechnen musste.</p>
<p>Eine kurze, klar definierte Liste von Ausnahmen bleibt bestehen -- Kleinlandwirtschaft, bestimmte wertschöpfende Bauleistungen, Steuerpflichtige der Einkommensteuer für Gebietsfremde, vollständig umsatzsteuerbefreite Tätigkeiten außerhalb von Freihandelszonen sowie Uruguays vereinfachte Kleinstunternehmerregime. Über diese enge Liste hinaus berichtete die DGI in ihrer eigenen Ankündigung, dass die elektronische Rechnungsstellung bereits 98 % der landesweit ausgestellten Dokumentation abdeckte, noch bevor die Schließung in Kraft trat -- eine bemerkenswerte Adoptionsrate für eine Pflicht, die sich über mehr als ein Jahrzehnt entwickelt hatte.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-01-01-uruguay-universal-mandate-completes', 'fr', 'L''obligation de facturation électronique de l''Uruguay devient universelle', 'À compter du 1er janvier 2025, la quasi-totalité des contribuables à la TVA restants de l''Uruguay sont devenus émetteurs électroniques obligatoires, refermant une fenêtre d''exemption que la DGI avait maintenue sous diverses formes depuis le début du régime CFE en 2012 -- l''annonce de la DGI elle-même situait la documentation électronique à 98 % du total, avant même l''entrée en vigueur de la fermeture.', '<h3>🇺🇾 L''obligation de facturation électronique de l''Uruguay devient universelle</h3>
<p>Dans un communiqué officiel publié le 28 novembre 2024, la Dirección General Impositiva (DGI) de l''Uruguay a annoncé qu''à compter du 1er janvier 2025, la quasi-totalité des contribuables à la TVA restants -- y compris ceux relevant du régime « IVA Mínimo » (TVA minimale) -- deviendraient émetteurs électroniques obligatoires de Comprobante Fiscal Electrónico (CFE), refermant une fenêtre d''exemption que l''agence avait maintenue sous diverses formes depuis le début du régime CFE sous le Decreto 36/012 en 2012.</p>
<p>L''échéance elle-même remonte à la Resolución DGI 2548/023 (approuvée le 30 novembre 2023), qui a accordé aux contribuables déjà désignés pour une intégration obligatoire jusqu''au 31 décembre 2024 pour se conformer, et a exigé que toute personne s''enregistrant nouvellement à la TVA entre mai et décembre 2024 facture électroniquement avant le 1er janvier 2025.</p>
<p>Une courte liste définie d''exemptions subsiste -- petite agriculture, certains services de construction à valeur ajoutée, contribuables de l''impôt sur le revenu des non-résidents, activité entièrement exonérée de TVA hors zones franches, et les régimes simplifiés de micro-entreprises de l''Uruguay. Au-delà de cette liste restreinte, l''annonce de la DGI elle-même indiquait que la facturation électronique couvrait déjà 98 % de la documentation émise à l''échelle nationale, avant même l''entrée en vigueur de la fermeture -- un taux d''adoption frappant pour une obligation en gestation depuis plus d''une décennie.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-04-15-uruguay-cfe-v25-controls', '2026-04-15', '2026-04', 'Uruguay''s tax authority DGI rolled out new mandatory validation controls for its CFE electronic-invoicing format on 15 April 2026, part of the ongoing technical evolution of a system that''s been mandatory in some form since 2012 and universal since January 2025.', '<h3>🇺🇾 DGI tightens CFE validation with format v25.1''s new mandatory controls</h3>
<p>Uruguay''s Dirección General Impositiva (DGI) has continued evolving the technical specification behind its Comprobante Fiscal Electrónico (CFE) system even as the underlying mandate itself has stayed stable since becoming universal on 1 January 2025. New data fields and validations across several schema zones of CFE format v25 and v25.1 entered production on 3 March 2026.</p>
<p>Stricter mandatory controls followed on 15 April 2026, targeting invoice cross-reference and traceability data -- currency and exchange-rate fields -- along with tighter validation of authorized-representative and issuer RUC information. For businesses already issuing CFE, this is routine technical maintenance rather than a new compliance obligation, but it''s a reminder that a mature, decade-old mandate can still carry real, current technical work.</p>
<p>Businesses relying on a third-party e-invoicing provider should confirm directly that their provider has certified against the current schema version rather than assuming ongoing compatibility -- DGI''s approach of periodic, dated schema revisions has been a consistent feature of the CFE system since its earliest days.</p>', 'https://www.efactura.dgi.gub.uy/', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-04-15-uruguay-cfe-v25-controls', id FROM countries WHERE name_en = 'Uruguay';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-15-uruguay-cfe-v25-controls', 'en', 'DGI tightens CFE validation with format v25.1''s new mandatory controls', 'Uruguay''s tax authority DGI rolled out new mandatory validation controls for its CFE electronic-invoicing format on 15 April 2026, part of the ongoing technical evolution of a system that''s been mandatory in some form since 2012 and universal since January 2025.', '<h3>🇺🇾 DGI tightens CFE validation with format v25.1''s new mandatory controls</h3>
<p>Uruguay''s Dirección General Impositiva (DGI) has continued evolving the technical specification behind its Comprobante Fiscal Electrónico (CFE) system even as the underlying mandate itself has stayed stable since becoming universal on 1 January 2025. New data fields and validations across several schema zones of CFE format v25 and v25.1 entered production on 3 March 2026.</p>
<p>Stricter mandatory controls followed on 15 April 2026, targeting invoice cross-reference and traceability data -- currency and exchange-rate fields -- along with tighter validation of authorized-representative and issuer RUC information. For businesses already issuing CFE, this is routine technical maintenance rather than a new compliance obligation, but it''s a reminder that a mature, decade-old mandate can still carry real, current technical work.</p>
<p>Businesses relying on a third-party e-invoicing provider should confirm directly that their provider has certified against the current schema version rather than assuming ongoing compatibility -- DGI''s approach of periodic, dated schema revisions has been a consistent feature of the CFE system since its earliest days.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-15-uruguay-cfe-v25-controls', 'es', 'La DGI refuerza la validación del CFE con los nuevos controles obligatorios del formato v25.1', 'La autoridad tributaria de Uruguay, la DGI, implementó nuevos controles de validación obligatorios para su formato de facturación electrónica CFE el 15 de abril de 2026, como parte de la evolución técnica continua de un sistema que ha sido obligatorio en alguna forma desde 2012 y universal desde enero de 2025.', '<h3>🇺🇾 La DGI refuerza la validación del CFE con los nuevos controles obligatorios del formato v25.1</h3>
<p>La Dirección General Impositiva (DGI) de Uruguay ha seguido haciendo evolucionar la especificación técnica de su sistema de Comprobante Fiscal Electrónico (CFE), incluso mientras el mandato subyacente se ha mantenido estable desde que se volvió universal el 1 de enero de 2025. Nuevos campos de datos y validaciones en varias zonas del esquema del formato CFE v25 y v25.1 entraron en producción el 3 de marzo de 2026.</p>
<p>Controles obligatorios más estrictos siguieron el 15 de abril de 2026, orientados a los datos de referencia cruzada y trazabilidad de las facturas -- campos de moneda y tipo de cambio -- junto con una validación más estricta de la información del representante autorizado y del RUC del emisor. Para las empresas que ya emiten CFE, se trata de un mantenimiento técnico de rutina y no de una nueva obligación de cumplimiento, pero es un recordatorio de que un mandato maduro, de una década de antigüedad, todavía puede conllevar trabajo técnico real y actual.</p>
<p>Las empresas que dependen de un proveedor externo de facturación electrónica deberían confirmar directamente que su proveedor está certificado para la versión actual del esquema, en lugar de asumir una compatibilidad continuada -- el enfoque de la DGI de revisiones periódicas y fechadas del esquema ha sido una característica constante del sistema CFE desde sus primeros días.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-15-uruguay-cfe-v25-controls', 'de', 'Die DGI verschärft die CFE-Validierung mit den neuen verpflichtenden Kontrollen des Formats v25.1', 'Uruguays Steuerbehörde DGI hat am 15. April 2026 neue verpflichtende Validierungskontrollen für ihr E-Rechnungsformat CFE eingeführt, als Teil der laufenden technischen Weiterentwicklung eines Systems, das seit 2012 in irgendeiner Form verpflichtend und seit Januar 2025 universell ist.', '<h3>🇺🇾 Die DGI verschärft die CFE-Validierung mit den neuen verpflichtenden Kontrollen des Formats v25.1</h3>
<p>Uruguays Dirección General Impositiva (DGI) hat die technische Spezifikation ihres Comprobante-Fiscal-Electrónico(CFE)-Systems weiter ausgebaut, auch wenn die zugrunde liegende Pflicht selbst seit ihrer Universalisierung am 1. Januar 2025 stabil geblieben ist. Neue Datenfelder und Validierungen in mehreren Schemabereichen der CFE-Formate v25 und v25.1 gingen am 3. März 2026 in den Produktivbetrieb.</p>
<p>Strengere verpflichtende Kontrollen folgten am 15. April 2026 und zielten auf Querverweis- und Rückverfolgbarkeitsdaten von Rechnungen -- Währungs- und Wechselkursfelder -- sowie auf eine strengere Validierung der Angaben zu bevollmächtigten Vertretern und der RUC-Nummer des Ausstellers. Für Unternehmen, die bereits CFE ausstellen, handelt es sich um routinemäßige technische Wartung und nicht um eine neue Compliance-Pflicht, doch es ist eine Erinnerung daran, dass eine ausgereifte, jahrzehntealte Pflicht weiterhin echte, aktuelle technische Arbeit mit sich bringen kann.</p>
<p>Unternehmen, die auf einen externen E-Invoicing-Anbieter setzen, sollten direkt bestätigen, dass ihr Anbieter für die aktuelle Schemaversion zertifiziert ist, statt fortlaufende Kompatibilität anzunehmen -- der Ansatz der DGI, das Schema regelmäßig und datiert zu überarbeiten, ist seit den frühesten Tagen des CFE-Systems ein durchgängiges Merkmal.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-15-uruguay-cfe-v25-controls', 'fr', 'La DGI renforce la validation du CFE avec les nouveaux contrôles obligatoires du format v25.1', 'L''administration fiscale uruguayenne, la DGI, a déployé le 15 avril 2026 de nouveaux contrôles de validation obligatoires pour son format de facturation électronique CFE, dans le cadre de l''évolution technique continue d''un système obligatoire sous une forme ou une autre depuis 2012 et universel depuis janvier 2025.', '<h3>🇺🇾 La DGI renforce la validation du CFE avec les nouveaux contrôles obligatoires du format v25.1</h3>
<p>La Dirección General Impositiva (DGI) de l''Uruguay a continué de faire évoluer la spécification technique de son système de Comprobante Fiscal Electrónico (CFE), alors même que l''obligation sous-jacente est restée stable depuis qu''elle est devenue universelle le 1er janvier 2025. De nouveaux champs de données et validations couvrant plusieurs zones du schéma des formats CFE v25 et v25.1 sont entrés en production le 3 mars 2026.</p>
<p>Des contrôles obligatoires plus stricts ont suivi le 15 avril 2026, visant les données de référence croisée et de traçabilité des factures -- champs de devise et de taux de change -- ainsi qu''une validation renforcée des informations relatives au représentant autorisé et au RUC de l''émetteur. Pour les entreprises émettant déjà des CFE, il s''agit d''une maintenance technique de routine plutôt que d''une nouvelle obligation de conformité, mais cela rappelle qu''une obligation mature, vieille d''une décennie, peut encore impliquer un travail technique réel et actuel.</p>
<p>Les entreprises qui dépendent d''un prestataire tiers de facturation électronique devraient confirmer directement que leur prestataire est certifié pour la version actuelle du schéma plutôt que de présumer d''une compatibilité continue -- l''approche de la DGI consistant à réviser périodiquement et de manière datée le schéma est une caractéristique constante du système CFE depuis ses débuts.</p>');
